#pragma once
#include <iomanip>

template<class Read> void corpusAutoDiagnostic(juce::AudioProcessor* p,juce::AudioBuffer<float>& audio,juce::MidiBuffer& midi,Read value,const char* recording,const std::string& path){
 auto check=[](bool ok,const char* why){if(!ok)throw std::runtime_error(why);};
 auto heap=[&](const char* name,int n){std::vector<double> x(n);check(za_native_gfx_heap_copy(p,name,x.data(),n)==n,"Auto diagnostic heap read failed");return x;};
 int n=int(value("grain_count"));auto g=heap("grain_base",n*64),xc=heap("xc_features",n*112),a=heap("auto_sources",8),neighbors=heap("xc_neighbors",n*16);
 std::ofstream graph(path+".graph.csv");graph<<"id,n0,n1,n2,n3,next,eligible\n";for(int id=0;id<n;++id)graph<<id<<','<<int(neighbors[id*16])<<','<<int(neighbors[id*16+1])<<','<<int(neighbors[id*16+2])<<','<<int(neighbors[id*16+3])<<','<<int(xc[id*112+95])<<','<<(g[id*64+6]>.00001 && g[id*64+9]<.5)<<'\n';graph.close();
 std::vector<double> durations,boundaries,spans,outside;std::ofstream grains(path+".grains.csv");grains<<"id,start_s,duration_s,motion_raw,motion,brightness_raw,brightness,sensor_coverage,cached_playback_start_s,cached_playback_duration_s,playback_outside_anchor\n";
 for(int id=0;id<n;++id){double rate=g[id*64+4],start=g[id*64+2],end=start+g[id*64+3],ps=xc[id*112+88],pf=xc[id*112+89];double out=pf>0?1-std::max(0.,std::min(end,ps+pf)-std::max(start,ps))/pf:0;
  durations.push_back((end-start)/rate);boundaries.push_back(start/rate);spans.push_back(pf/rate);outside.push_back(out);grains<<id<<','<<start/rate<<','<<(end-start)/rate<<','<<g[id*64+14]<<','<<g[id*64+19]<<','<<g[id*64+12]<<','<<g[id*64+17]<<','<<g[id*64+49]<<','<<ps/rate<<','<<pf/rate<<','<<out<<'\n';}
 boundaries.push_back(value("total_seconds"));std::sort(durations.begin(),durations.end());std::sort(spans.begin(),spans.end());
 auto percentile=[](const std::vector<double>& x,double q){return x[std::min(x.size()-1,size_t(q*(x.size()-1)))];};
 juce::AudioFormatManager formats;formats.registerBasicFormats();std::unique_ptr<juce::AudioFormatReader> reader(formats.createReaderFor(juce::File(juce::String::fromUTF8(recording))));check(bool(reader),"Auto waveform reader");
 int hop=int(std::round(reader->sampleRate*.01)),chunkFrames=hop*200;juce::AudioBuffer<float> chunk(2,chunkFrames);std::vector<double> db,brightness,peak;double power=0,diff=0,mx=0,lastL=0,lastR=0;int used=0;
 for(int64_t pos=0;pos<reader->lengthInSamples;pos+=chunkFrames){int count=int(std::min<int64_t>(chunkFrames,reader->lengthInSamples-pos));chunk.clear();check(reader->read(&chunk,0,count,pos,true,true),"Auto waveform decode");for(int i=0;i<count;++i){double l=chunk.getSample(0,i),r=reader->numChannels>1?chunk.getSample(1,i):l;power+=(l*l+r*r)*.5;mx=std::max(mx,std::max(std::abs(l),std::abs(r)));if(used)diff+=((l-lastL)*(l-lastL)+(r-lastR)*(r-lastR))*.5;lastL=l;lastR=r;++used;
   if(used==hop){db.push_back(20*std::log10(std::max(1e-12,std::sqrt(power/used))));brightness.push_back(std::log(1+20*std::sqrt(std::clamp(diff/std::max(1e-20,4*power),0.,1.)))/std::log(21));peak.push_back(mx);power=diff=mx=0;used=0;}}}
 auto sortedDb=db;std::sort(sortedDb.begin(),sortedDb.end());double activeFloor=std::max(-70.,percentile(sortedDb,.9)-42);int events=0,near10=0,near20=0,internal30=0;double distanceSum=0;int last=-10;std::ofstream changes(path+".changes.csv");changes<<"time_s,rise_db,brightness_change,nearest_grain_boundary_ms\n";
 for(int i=1;i<int(db.size());++i){double rise=db[i]-db[i-1],brightChange=std::abs(brightness[i]-brightness[i-1]);if(i-last<3 || db[i]<activeFloor || !(rise>6 || brightChange>.2))continue;last=i;double t=i*.01;auto it=std::lower_bound(boundaries.begin(),boundaries.end(),t);double distance=it==boundaries.end()?1e9:std::abs(*it-t);if(it!=boundaries.begin())distance=std::min(distance,std::abs(*std::prev(it)-t));++events;near10+=distance<=.01;near20+=distance<=.02;internal30+=distance>=.03;distanceSum+=distance;changes<<t<<','<<rise<<','<<brightChange<<','<<distance*1000<<'\n';}
 int expanded=0;double outsideMean=0;for(double x:outside){expanded+=x>.1;outsideMean+=x;}
 int attackNoOverlap=0,bodyNoOverlap=0;double attackOutside=0,bodyOutside=0;
 for(int id=0;id<n;++id){double rate=g[id*64+4],lo=g[id*64+2],hi=lo+g[id*64+3],start=xc[id*112+88],full=xc[id*112+89];
  for(int kind=0;kind<2;++kind){double frames=std::min(full,rate*(kind==0?.256:.440));double overlap=std::max(0.,std::min(hi,start+frames)-std::max(lo,start));if(frames>0){if(kind==0){attackNoOverlap+=overlap==0;attackOutside+=1-overlap/frames;}else{bodyNoOverlap+=overlap==0;bodyOutside+=1-overlap/frames;}}}}
 std::ofstream json(path+".json");json<<std::setprecision(12)<<"{\n\"source_seconds\":"<<value("total_seconds")<<",\n\"manual_ms\":"<<corpusGet(p,5)<<",\n\"budget\":"<<value("grain_capacity")<<",\n\"final_grains\":"<<n<<",\n\"desired_sensors\":"<<value("auto_desired_cells")<<",\n\"budget_scale\":"<<value("auto_budget_scale")<<",\n\"coarsened_sources_flag\":"<<value("auto_budget_coarsened")<<",\n\"scout_probe_step_ms\":"<<a[6]*1000<<",\n\"scout_confidence\":"<<a[3]<<",\n\"target_sensor_ms\":"<<a[0]*1000<<",\n\"scout_probes\":"<<a[7]<<",\n\"scout_sparse_sources\":"<<value("auto_scout_sparse")<<",\n\"grain_min_ms\":"<<durations.front()*1000<<",\n\"grain_median_ms\":"<<percentile(durations,.5)*1000<<",\n\"grain_mean_ms\":"<<std::accumulate(durations.begin(),durations.end(),0.)/n*1000<<",\n\"grain_p90_ms\":"<<percentile(durations,.9)*1000<<",\n\"grain_max_ms\":"<<durations.back()*1000<<",\n\"cached_span_median_ms\":"<<percentile(spans,.5)*1000<<",\n\"cached_spans_with_over10pct_outside_anchor\":"<<expanded<<",\n\"mean_cached_span_fraction_outside_anchor\":"<<outsideMean/n<<",\n\"change_probes\":"<<events<<",\n\"change_probes_within10ms_boundary\":"<<near10<<",\n\"change_probes_within20ms_boundary\":"<<near20<<",\n\"change_probes_over30ms_from_boundary\":"<<internal30<<",\n\"mean_change_to_boundary_ms\":"<<(events?distanceSum/events*1000:0)<<"\n}\n";
 std::ofstream caps(path+".caps.json");caps<<"{\"anchor_count\":"<<n<<",\"assumed_event_ms\":800,\"attack_cap_ms\":256,\"body_cap_ms\":440,\"attack_no_overlap\":"<<attackNoOverlap<<",\"body_no_overlap\":"<<bodyNoOverlap<<",\"attack_outside_fraction\":"<<attackOutside/n<<",\"body_outside_fraction\":"<<bodyOutside/n<<",\"scope\":\"Model of existing cached-start and end-only event cap, xc renderer active, Core lanes, no pruning\"}\n";
 std::cout<<"AUTO budget="<<value("grain_capacity")<<" manual_ms="<<corpusGet(p,5)<<" final="<<n<<" desired_sensors="<<value("auto_desired_cells")<<" scout_step_ms="<<a[6]*1000<<" confidence="<<a[3]<<" sensor_target_ms="<<a[0]*1000<<" grains_min/median/max_ms="<<durations.front()*1000<<'/'<<percentile(durations,.5)*1000<<'/'<<durations.back()*1000<<" span_median_ms="<<percentile(spans,.5)*1000<<" expanded="<<expanded<<" change_probes="<<events<<" internal30ms="<<internal30<<" short_attack_no_anchor_overlap="<<attackNoOverlap<<std::endl;
 // Test actual scheduled source windows for the user's two maximum Floor lanes
 // with the ordinary 800-ms event, not only hypothetical caps on all anchors.
 if(corpusGet(p,5)==0 && value("grain_capacity")==8192){
  for(int lane=0;lane<12;++lane)corpusSet(p,86+lane*13,0);for(int lane=0;lane<2;++lane){corpusSet(p,86+lane*13,float(3072+128+(lane==0?3:1)));corpusSet(p,87+lane*13,1);for(int j=0;j<11;++j)corpusSet(p,88+lane*13+j,float(j==10?16254:2080638));}
  for(auto [id,x]:std::vector<std::pair<int,float>>{{25,800},{81,2},{82,0},{84,0},{85,-1},{76,0},{2,.35f},{12,1},{10,0}})corpusSet(p,id,x);
  std::ofstream emitted(path+".emitted.csv");emitted<<"note,grain,stage,when_s,anchor_start_s,anchor_duration_s,source_start_s,source_duration_s,audible_duration_s,source_fraction_outside_anchor,audible_fraction_outside_anchor\n";int all=0,none=0,attacks=0,attackNone=0;double outMean=0;
  for(int note=0;note<20;++note){corpusSet(p,11,float(12345+note*104729));audio.clear();midi.clear();p->processBlock(audio,midi);for(int b=0;b<200;++b){audio.clear();midi.clear();if(!b)midi.addEvent(juce::MidiMessage::noteOn(1,60,juce::uint8(100)),0);p->processBlock(audio,midi);}int count=int(value("record_n"));auto records=heap("record_base",count*20);for(int i=0;i<count;++i){auto* r=records.data()+i*20;int id=int(r[0]);double rate=g[id*64+4],lo=g[id*64+2],hi=lo+g[id*64+3],start=r[6],frames=r[7];double heard=std::min(frames,std::max(0.,.8*48000-r[2]));double overlap=std::max(0.,std::min(hi,start+frames)-std::max(lo,start)),actualOverlap=std::max(0.,std::min(hi,start+heard)-std::max(lo,start));double outside=frames>0?1-overlap/frames:0,actualOutside=heard>0?1-actualOverlap/heard:0;++all;none+=actualOverlap==0;outMean+=actualOutside;attacks+=int(r[14])==0;attackNone+=int(r[14])==0 && actualOverlap==0;emitted<<note<<','<<id<<','<<int(r[14])<<','<<r[2]/48000<<','<<lo/rate<<','<<(hi-lo)/rate<<','<<start/rate<<','<<frames/rate<<','<<heard/rate<<','<<outside<<','<<actualOutside<<'\n';}}
  std::cout<<"AUTO ACTUAL 20x800ms notes: choices="<<all<<" audible_no_anchor_overlap="<<none<<" attack_no_overlap="<<attackNone<<'/'<<attacks<<" mean_audible_outside="<<outMean/std::max(1,all)<<std::endl;
 }
}
